// monta o HTML do documento (tabelas por secao) e entrega como arquivo pro Gotenberg
const b = ($input.first().json.body || $input.first().json || {});
const dono = String(b.dono || '').replace(/[^0-9]/g, '');
if (!dono) return [];
const doc = b.doc || {};
const h = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const num = s => /^[\s\-+]*(R\$|US\$|\$|€)?\s*[\d.,]+\s*%?$/.test(String(s || '').trim());
const titulo = String(doc.titulo || 'Documento').substring(0, 120);
const sub = String(doc.subtitulo || '').substring(0, 200);
const tz = String(b.timezone || 'America/Sao_Paulo');
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: tz });
const secoes = (Array.isArray(doc.secoes) ? doc.secoes : []).slice(0, 12);
let corpo = '';
for (const s of secoes) {
  const cols = (Array.isArray(s.colunas) ? s.colunas : []).slice(0, 8).map(String);
  const linhas = (Array.isArray(s.linhas) ? s.linhas : []).slice(0, 200).map(l => Array.isArray(l) ? l.slice(0, 8) : [l]);
  const ncol = Math.max(cols.length, ...linhas.map(l => l.length), 1);
  corpo += `<h2>${h(s.titulo || '')}</h2><table>`;
  if (cols.length) corpo += '<thead><tr>' + cols.map((c, i) => `<th class="${i > 0 ? 'r' : ''}">${h(c)}</th>`).join('') + '</tr></thead>';
  corpo += '<tbody>' + linhas.map(l => '<tr>' + Array.from({ length: ncol }, (_, i) => `<td class="${num(l[i]) && i > 0 ? 'r' : ''}">${h(l[i] == null ? '' : l[i])}</td>`).join('') + '</tr>').join('') + '</tbody>';
  if (s.total && (s.total.rotulo || s.total.valor)) corpo += `<tfoot><tr><td colspan="${Math.max(ncol - 1, 1)}">${h(s.total.rotulo || 'Total')}</td><td class="r">${h(s.total.valor || '')}</td></tr></tfoot>`;
  corpo += '</table>';
}
const tg = doc.total_geral;
if (tg && (tg.rotulo || tg.valor)) corpo += `<div class="tg"><span>${h(tg.rotulo || 'Total')}</span><span>${h(tg.valor || '')}</span></div>`;
if (doc.observacao) corpo += `<p class="obs">${h(String(doc.observacao).substring(0, 1200))}</p>`;
const html = `<!doctype html><html><head><meta charset="utf-8"><style>
@page { size: A4; margin: 18mm 16mm; }
body { font-family: 'DejaVu Sans', Arial, sans-serif; color: #1d1d1b; font-size: 11pt; }
h1 { font-size: 19pt; color: #1f3b2d; margin: 0 0 2pt; } .sub { color: #666; font-size: 9.5pt; margin-bottom: 14pt; }
h2 { font-size: 12pt; margin: 16pt 0 5pt; color: #1f3b2d; }
table { width: 100%; border-collapse: collapse; } th { background: #e8efe9; text-align: left; font-size: 9.5pt; padding: 5pt 6pt; border-bottom: 1px solid #1f3b2d; }
td { padding: 4pt 6pt; border-bottom: 0.5px solid #ddd; font-size: 10pt; } .r { text-align: right; white-space: nowrap; }
tfoot td { font-weight: bold; background: #f4f4f4; border-top: 1px solid #999; }
.tg { margin-top: 16pt; background: #1f3b2d; color: #fff; padding: 8pt 10pt; font-weight: bold; font-size: 13pt; display: flex; justify-content: space-between; }
.obs { margin-top: 12pt; color: #555; font-size: 9.5pt; } .rod { margin-top: 22pt; color: #999; font-size: 8pt; }
</style></head><body><h1>${h(titulo)}</h1><div class="sub">${h(sub ? sub + ' · ' : '')}gerado em ${h(hoje)}</div>${corpo}<div class="rod">Documento gerado pela assistente${b.nome ? ' a pedido de ' + h(b.nome) : ''}.</div></body></html>`;
const slug = titulo.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').substring(0, 60) || 'documento';
return [{ json: { dono, titulo, doc_name: slug + '.pdf', legenda: String(doc.legenda || ('📄 ' + titulo)).substring(0, 500) },
          binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html' } } }];

// pega o PDF (ou o erro) e monta o envio: documento se deu certo, texto avisando se falhou
const it = $input.first();
const base = $('Montar HTML').first().json;
let b64 = '';
try { if (!(it.json && it.json.error)) { const buf = await this.helpers.getBinaryDataBuffer(0, 'pdf'); if (buf && buf.length > 500) b64 = buf.toString('base64'); } } catch (e) {}
const ok = !!b64;
const body = ok ? { number: base.dono, type: 'document', file: 'data:application/pdf;base64,' + b64, docName: base.doc_name, text: base.legenda }
                : { number: base.dono, text: 'Nao consegui gerar o PDF agora (o gerador nao respondeu). Me pede de novo em um minuto?' };
return [{ json: { ok, url: ok ? 'https://engsolucao.uazapi.com/send/media' : 'https://engsolucao.uazapi.com/send/text', body, dono: base.dono, titulo: base.titulo, legenda: base.legenda } }];

// registra na memoria o que foi realmente enviado
const env = $input.first().json || {};
const m = $('Montar Envio').first().json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''").replace(/\$+/g, x => x.length === 1 ? "' || chr(36) || '" : "' || repeat(chr(36), " + x.length + ") || '");
const enviado = !env.error;
const txt = m.ok ? (m.legenda + (enviado ? ' [PDF enviado]' : ' [falhou o envio do PDF]')) : 'Nao consegui gerar o PDF agora (o gerador nao respondeu).';
return [{ json: { sql: "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(txt) + "', '" + esc(m.dono) + "');" } }];
